<?php

/* @autogenerated */
declare(strict_types=1);

require_once __DIR__ . '/FormsTestCase.php';

use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use DI\ContainerBuilder;
use Slim\Psr7\Factory\ServerRequestFactory;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms\LoginForm;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Application\DelegateLogin;
use Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\ChangePasswordUsecase;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\RegisterUserUsecase;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Unit tests for {@see LoginForm} step integration.
 */
#[AllowMockObjectsWithoutExpectations]
final class LoginFormStepUnitTest extends FormsTestCase
{
    /**
     * Verifies authenticate() uses StepInput values.
     */
    public function testAuthenticateUsesStepInput(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid profile',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://example.com');
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $client = new ClientData('client-123', ['code'], true);
        $authRequest = new AuthenticationRequest(
            client: $client,
            scope: 'openid profile',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );

        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: new ChallengesState(),
            body: [
                'username' => 'user@example.com',
                'password' => 'enc-pass',
                'csid' => 'csid-123'
            ],
            request: $request
        );

        $authResponse = $this->createMock(PublicLoginAuthResponse::class);

        $securer = $this->createMock(HtmlSecurer::class);
        $securer->expects($this->once())
            ->method('decrypt')
            ->with('enc-pass')
            ->willReturn('plain-pass');

        $authenticator = $this->createMock(AuthenticateUser::class);
        $authenticator->expects($this->once())
            ->method('authenticate')
            ->with(
                $authRequest,
                $this->isInstanceOf(ChallengesState::class),
                'tenant1',
                'user@example.com',
                'plain-pass',
                'https://example.com/oauth/openid/tenant1',
                'csid-123',
                'state-xyz',
                'nonce-abc'
            )
            ->willReturn($authResponse);

        $form = new LoginForm(
            $this->createMock(MessageProvider::class),
            $authenticator,
            $this->createMock(DecorateHtml::class),
            $securer,
            $this->createMock(DelegateLogin::class),
            $this->createMock(ChangePasswordUsecase::class),
            $this->createMock(RegisterUserUsecase::class),
            $this->createMock(RequestMagicLinkUsecase::class),
        );

        $result = $form->authenticate($input);

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertInstanceOf(PublicLoginAuthResponse::class, $result->authResponse);
        $this->assertInstanceOf(ChallengesState::class, $result->challenges);
        $this->assertSame('user@example.com', $result->challenges->username);
        $this->assertSame($input->challenges->withMfa, $result->challenges->withMfa);
        $this->assertSame($input->challenges->session, $result->challenges->session);
    }

    /**
     * login_hint only prefills the username, escaped: the user still proves who they are (task 067).
     */
    public function testTheLoginHintOnlyPrefillsTheUsername(): void
    {
        $page = $this->renderLogin(['login_hint' => 'a"<b>@example.com']);

        $this->assertStringContainsString('name="username" value="a&quot;&lt;b&gt;@example.com"', $page);
    }

    /**
     * The magic link gives no second factor, so it is not offered when acr_values asks for one.
     */
    public function testTheMagicLinkIsNotOfferedWhenMfaIsRequested(): void
    {
        $this->assertStringContainsString('value="magic-link"', $this->renderLogin([]));
        $this->assertStringNotContainsString('value="magic-link"', $this->renderLogin(['acr_values' => 'urn:lugh:acr:mfa']));
    }

    private function renderLogin(array $query): string
    {
        $page = '';
        $decorator = $this->createMock(DecorateHtml::class);
        $decorator->method('getFullPage')->willReturnCallback(function ($request, string $title, string $content) use (&$page): string {
            $page = $content;
            return $content;
        });
        $magicLink = $this->createMock(RequestMagicLinkUsecase::class);
        $magicLink->method('isEnabled')->willReturn(true);
        $form = new LoginForm(
            $this->createMock(MessageProvider::class),
            $this->createMock(AuthenticateUser::class),
            $decorator,
            $this->createMock(HtmlSecurer::class),
            $this->createMock(DelegateLogin::class),
            $this->createMock(ChangePasswordUsecase::class),
            $this->createMock(RegisterUserUsecase::class),
            $magicLink,
        );

        $form->render($this->buildInput([], new ChallengesState(), $query), new Slim\Psr7\Response(), null);

        return $page;
    }
}
